sys_variable_value.value:
(function() {
    var outputs_obj = {
        chat_id: '',
        status: 'success',
        error_message: ''
    };

    try {
        var helper = new x_1815796_itsmgr_0.AiBotHelper();
        
        // 1. Call the creation logic in your Script Include
        // This hits the 'Create a new chat' REST Message
        var new_id = helper.createChatSession(inputs.model || "gemma3:27b");

        // 2. Defensive Check: Did it return an error string or a UUID?
        if (!new_id || new_id.indexOf('Error:') === 0) {
            outputs_obj.status = 'error';
            outputs_obj.error_message = new_id || "Unknown error during chat creation.";
        } else {
            outputs_obj.chat_id = new_id;
        }

    } catch (ex) {
        outputs_obj.status = 'error';
        outputs_obj.error_message = "Action Exception: " + ex.message;
    }

    // Map to Action Outputs
    outputs.chat_id = outputs_obj.chat_id;
    outputs.status = outputs_obj.status;
    outputs.error_message = outputs_obj.error_message;

})();

